ALTER TABLE "Course"
ADD COLUMN "level" TEXT NOT NULL DEFAULT 'iniciacion',
ADD COLUMN "category" TEXT NOT NULL DEFAULT 'general',
ADD COLUMN "durationMinutes" INTEGER NOT NULL DEFAULT 60;

INSERT INTO "Course" (
  "id", "slug", "title", "description", "price", "currency", "pricingType",
  "status", "publishedAt", "rankRequirement", "level", "category", "durationMinutes", "updatedAt"
) VALUES
  ('crs_lyra_ia', 'lyra-ia-desde-cero', 'Inteligencia artificial desde cero', 'Comprende cómo funciona la IA generativa, úsala con criterio y conviértela en una herramienta práctica para tu vida y trabajo.', 0, 'MXN', 'FREE', 'PUBLISHED', CURRENT_TIMESTAMP, 'ASTRA', 'iniciacion', 'inteligencia-artificial', 90, CURRENT_TIMESTAMP),
  ('crs_lyra_agentes', 'lyra-agentes-de-ia', 'Agentes de IA: asistentes que ejecutan tareas', 'Aprende qué diferencia a un agente de un chat, cómo configurarlo y cómo supervisar sus acciones dentro de un flujo de trabajo.', 0, 'MXN', 'FREE', 'PUBLISHED', CURRENT_TIMESTAMP, 'ASTRA', 'intermedio', 'automatizacion', 120, CURRENT_TIMESTAMP),
  ('crs_lyra_academia', 'lyra-academia', 'Academia Lyra: aprende, crea y publica cursos', 'Recorre la Academia como estudiante y creador: desde elegir un curso hasta estructurar contenido y publicar una oferta clara.', 0, 'MXN', 'FREE', 'PUBLISHED', CURRENT_TIMESTAMP, 'ASTRA', 'iniciacion', 'academia', 90, CURRENT_TIMESTAMP),
  ('crs_lyra_contenido', 'lyra-contenido-digital-con-ia', 'Contenido digital con IA: de la idea a la publicación', 'Crea piezas coherentes para tus canales con apoyo de IA, manteniendo una voz propia y revisando cada publicación antes de compartirla.', 0, 'MXN', 'FREE', 'PUBLISHED', CURRENT_TIMESTAMP, 'ASTRA', 'intermedio', 'contenido-digital', 120, CURRENT_TIMESTAMP),
  ('crs_lyra_negocio', 'lyra-negocio-digital', 'Negocio digital con Lyra: comunidad, confianza y crecimiento', 'Organiza una presencia digital útil y sostenible: escucha a tu comunidad, acompaña prospectos y mide resultados sin promesas exageradas.', 0, 'MXN', 'FREE', 'PUBLISHED', CURRENT_TIMESTAMP, 'ASTRA', 'avanzado', 'negocio-digital', 150, CURRENT_TIMESTAMP)
ON CONFLICT ("id") DO NOTHING;

INSERT INTO "Lesson" (
  "id", "courseId", "title", "description", "content", "videoUrl", "durationSeconds",
  "isPublished", "rankRequirement", "position", "updatedAt"
) VALUES
  ('crs_lyra_ia_lesson_1', 'crs_lyra_ia', 'Qué es la inteligencia artificial', 'Distingue IA, aprendizaje automático e IA generativa con ejemplos cotidianos.', 'Distingue IA, aprendizaje automático e IA generativa con ejemplos cotidianos.', '', 600, true, 'ASTRA', 0, CURRENT_TIMESTAMP),
  ('crs_lyra_ia_lesson_2', 'crs_lyra_ia', 'Cómo aprende y responde un modelo', 'Entiende datos, patrones, contexto y por qué una respuesta no equivale a una búsqueda.', 'Entiende datos, patrones, contexto y por qué una respuesta no equivale a una búsqueda.', '', 900, true, 'ASTRA', 1, CURRENT_TIMESTAMP),
  ('crs_lyra_ia_lesson_3', 'crs_lyra_ia', 'Prompts claros y útiles', 'Define objetivo, contexto, audiencia, restricciones y formato para obtener mejores resultados.', 'Define objetivo, contexto, audiencia, restricciones y formato para obtener mejores resultados.', '', 900, true, 'ASTRA', 2, CURRENT_TIMESTAMP),
  ('crs_lyra_ia_lesson_4', 'crs_lyra_ia', 'Errores, límites y verificación', 'Detecta alucinaciones, sesgos y datos dudosos; comprueba antes de tomar decisiones.', 'Detecta alucinaciones, sesgos y datos dudosos; comprueba antes de tomar decisiones.', '', 900, true, 'ASTRA', 3, CURRENT_TIMESTAMP),
  ('crs_lyra_ia_lesson_5', 'crs_lyra_ia', 'IA responsable y privacidad', 'Decide qué información compartir y cuándo una persona debe revisar el resultado.', 'Decide qué información compartir y cuándo una persona debe revisar el resultado.', '', 600, true, 'ASTRA', 4, CURRENT_TIMESTAMP),
  ('crs_lyra_ia_lesson_6', 'crs_lyra_ia', 'Práctica: resuelve una tarea real', 'Completa un flujo de trabajo de principio a fin y evalúa el resultado con una lista de criterios.', 'Completa un flujo de trabajo de principio a fin y evalúa el resultado con una lista de criterios.', '', 900, true, 'ASTRA', 5, CURRENT_TIMESTAMP),

  ('crs_lyra_agentes_lesson_1', 'crs_lyra_agentes', 'Qué es un agente de IA', 'Conoce sus objetivos, instrucciones, contexto, herramientas y límites de autonomía.', 'Conoce sus objetivos, instrucciones, contexto, herramientas y límites de autonomía.', '', 900, true, 'ASTRA', 0, CURRENT_TIMESTAMP),
  ('crs_lyra_agentes_lesson_2', 'crs_lyra_agentes', 'Elegir el agente adecuado en Lyra', 'Relaciona necesidades de atención, prospección, contenido y seguimiento con el agente correspondiente.', 'Relaciona necesidades de atención, prospección, contenido y seguimiento con el agente correspondiente.', '', 1200, true, 'ASTRA', 1, CURRENT_TIMESTAMP),
  ('crs_lyra_agentes_lesson_3', 'crs_lyra_agentes', 'Instrucciones, tono y contexto', 'Escribe un brief claro con objetivo, audiencia, ejemplos y condiciones de escalamiento.', 'Escribe un brief claro con objetivo, audiencia, ejemplos y condiciones de escalamiento.', '', 1200, true, 'ASTRA', 2, CURRENT_TIMESTAMP),
  ('crs_lyra_agentes_lesson_4', 'crs_lyra_agentes', 'Herramientas, permisos y canales', 'Revisa las conexiones disponibles y aplica el principio de acceso mínimo necesario.', 'Revisa las conexiones disponibles y aplica el principio de acceso mínimo necesario.', '', 1200, true, 'ASTRA', 3, CURRENT_TIMESTAMP),
  ('crs_lyra_agentes_lesson_5', 'crs_lyra_agentes', 'Supervisión y transferencia a una persona', 'Define aprobaciones, señales de riesgo y el momento para pasar una conversación a un humano.', 'Define aprobaciones, señales de riesgo y el momento para pasar una conversación a un humano.', '', 1200, true, 'ASTRA', 4, CURRENT_TIMESTAMP),
  ('crs_lyra_agentes_lesson_6', 'crs_lyra_agentes', 'Práctica: diseña un flujo asistido', 'Construye y prueba un proceso acotado; mide calidad, tiempo ahorrado y casos que requieren revisión.', 'Construye y prueba un proceso acotado; mide calidad, tiempo ahorrado y casos que requieren revisión.', '', 1200, true, 'ASTRA', 5, CURRENT_TIMESTAMP),

  ('crs_lyra_academia_lesson_1', 'crs_lyra_academia', 'Explorar el catálogo y elegir un curso', 'Usa filtros, revisa temarios y define objetivos de aprendizaje antes de inscribirte.', 'Usa filtros, revisa temarios y define objetivos de aprendizaje antes de inscribirte.', '', 600, true, 'ASTRA', 0, CURRENT_TIMESTAMP),
  ('crs_lyra_academia_lesson_2', 'crs_lyra_academia', 'Diseñar resultados de aprendizaje', 'Convierte una idea en resultados concretos que el estudiante pueda demostrar.', 'Convierte una idea en resultados concretos que el estudiante pueda demostrar.', '', 900, true, 'ASTRA', 1, CURRENT_TIMESTAMP),
  ('crs_lyra_academia_lesson_3', 'crs_lyra_academia', 'Estructurar módulos y lecciones', 'Ordena el contenido de lo esencial a lo avanzado e incluye ejercicios aplicables.', 'Ordena el contenido de lo esencial a lo avanzado e incluye ejercicios aplicables.', '', 900, true, 'ASTRA', 2, CURRENT_TIMESTAMP),
  ('crs_lyra_academia_lesson_4', 'crs_lyra_academia', 'Preparar materiales y vistas previas', 'Organiza videos, descripciones y recursos; comprueba que los enlaces sean accesibles.', 'Organiza videos, descripciones y recursos; comprueba que los enlaces sean accesibles.', '', 900, true, 'ASTRA', 3, CURRENT_TIMESTAMP),
  ('crs_lyra_academia_lesson_5', 'crs_lyra_academia', 'Publicar y presentar tu curso', 'Revisa título, descripción, precio, moneda y requisitos antes de publicar.', 'Revisa título, descripción, precio, moneda y requisitos antes de publicar.', '', 600, true, 'ASTRA', 4, CURRENT_TIMESTAMP),
  ('crs_lyra_academia_lesson_6', 'crs_lyra_academia', 'Ventas, pagos y experiencia del estudiante', 'Comprende el checkout actual de Mercado Pago, la comisión publicada y cómo acompañar al estudiante.', 'Comprende el checkout actual de Mercado Pago, la comisión publicada y cómo acompañar al estudiante.', '', 900, true, 'ASTRA', 5, CURRENT_TIMESTAMP),

  ('crs_lyra_contenido_lesson_1', 'crs_lyra_contenido', 'Pilares de contenido y audiencia', 'Define a quién ayudas, qué necesita y qué temas sostienen tu comunicación.', 'Define a quién ayudas, qué necesita y qué temas sostienen tu comunicación.', '', 900, true, 'ASTRA', 0, CURRENT_TIMESTAMP),
  ('crs_lyra_contenido_lesson_2', 'crs_lyra_contenido', 'Ideas y calendario editorial', 'Transforma preguntas frecuentes en una agenda realista para tus canales.', 'Transforma preguntas frecuentes en una agenda realista para tus canales.', '', 900, true, 'ASTRA', 1, CURRENT_TIMESTAMP),
  ('crs_lyra_contenido_lesson_3', 'crs_lyra_contenido', 'Escritura y adaptación por canal', 'Crea borradores y adapta extensión, tono y llamada a la acción sin repetir el mismo texto.', 'Crea borradores y adapta extensión, tono y llamada a la acción sin repetir el mismo texto.', '', 1200, true, 'ASTRA', 2, CURRENT_TIMESTAMP),
  ('crs_lyra_contenido_lesson_4', 'crs_lyra_contenido', 'Imágenes y videos con el Estudio Creativo', 'Prepara prompts visuales, selecciona formato y revisa el resultado antes de publicarlo.', 'Prepara prompts visuales, selecciona formato y revisa el resultado antes de publicarlo.', '', 1200, true, 'ASTRA', 3, CURRENT_TIMESTAMP),
  ('crs_lyra_contenido_lesson_5', 'crs_lyra_contenido', 'Edición, derechos y revisión', 'Comprueba exactitud, permisos, marcas y elementos que necesitan edición humana.', 'Comprueba exactitud, permisos, marcas y elementos que necesitan edición humana.', '', 900, true, 'ASTRA', 4, CURRENT_TIMESTAMP),
  ('crs_lyra_contenido_lesson_6', 'crs_lyra_contenido', 'Práctica: una campaña de una semana', 'Entrega un calendario con textos y una pieza visual coherentes con tu objetivo.', 'Entrega un calendario con textos y una pieza visual coherentes con tu objetivo.', '', 1200, true, 'ASTRA', 5, CURRENT_TIMESTAMP),

  ('crs_lyra_negocio_lesson_1', 'crs_lyra_negocio', 'Propuesta de valor y público', 'Explica con claridad a quién ayudas, qué problema atiendes y qué resultado puedes respaldar.', 'Explica con claridad a quién ayudas, qué problema atiendes y qué resultado puedes respaldar.', '', 1200, true, 'ASTRA', 0, CURRENT_TIMESTAMP),
  ('crs_lyra_negocio_lesson_2', 'crs_lyra_negocio', 'Perfil y presencia digital', 'Alinea biografía, canales y contenido con una identidad profesional consistente.', 'Alinea biografía, canales y contenido con una identidad profesional consistente.', '', 1200, true, 'ASTRA', 1, CURRENT_TIMESTAMP),
  ('crs_lyra_negocio_lesson_3', 'crs_lyra_negocio', 'Conversaciones y seguimiento respetuoso', 'Registra el consentimiento, responde dudas y da seguimiento sin presión ni mensajes engañosos.', 'Registra el consentimiento, responde dudas y da seguimiento sin presión ni mensajes engañosos.', '', 1200, true, 'ASTRA', 2, CURRENT_TIMESTAMP),
  ('crs_lyra_negocio_lesson_4', 'crs_lyra_negocio', 'Comunidad y relaciones a largo plazo', 'Diseña una rutina de bienvenida, contenido útil y atención a preguntas frecuentes.', 'Diseña una rutina de bienvenida, contenido útil y atención a preguntas frecuentes.', '', 1200, true, 'ASTRA', 3, CURRENT_TIMESTAMP),
  ('crs_lyra_negocio_lesson_5', 'crs_lyra_negocio', 'Medir resultados y mejorar', 'Usa indicadores básicos de alcance, respuesta y conversión para ajustar el proceso.', 'Usa indicadores básicos de alcance, respuesta y conversión para ajustar el proceso.', '', 900, true, 'ASTRA', 4, CURRENT_TIMESTAMP),
  ('crs_lyra_negocio_lesson_6', 'crs_lyra_negocio', 'Práctica: plan de crecimiento de 30 días', 'Entrega un plan semanal con acciones, métricas y límites claros para evaluar resultados.', 'Entrega un plan semanal con acciones, métricas y límites claros para evaluar resultados.', '', 1500, true, 'ASTRA', 5, CURRENT_TIMESTAMP)
ON CONFLICT ("id") DO NOTHING;
